// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(uint256 ts, uint256 difficulty, address actor) public {
        // keep the admissible domain wide; only require a plain EOA player
        vm.assume(actor != address(0) && actor.code.length == 0);

        vm.warp(ts);
        vm.roll(difficulty);

        // The reference contract performs NO external transfer when randomness == 1,
        // so play() succeeds; the mutant pays out there and its transfer to the bank
        // (this test contract, which has no receive) reverts. Restrict the domain to
        // the randomness == 1 branch so the reference holds for EVERY admissible input.
        uint256 rnd = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
        vm.assume(rnd == 1);

        vm.deal(actor, 10);
        vm.prank(actor);
        bool ok;
        try c.play{value: 10}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: always succeeds here (pot left at 10). Mutant: reverts.
        assertTrue(ok);
    }
}
